Read this minimal reverse-mode tape. What does <code>main</code> print, and what does the line <code>adj[n.p1] += adj[i] * n.d1;</code> do that a plain assignment would not?<br><pre><code>#include &lt;cmath&gt;
#include &lt;cstdio&gt;
#include &lt;vector&gt;

// Global tape: each node stores its parents and local partial derivatives.
struct Tape {
    struct Node { int p1, p2; double d1, d2; };  // parent index or -1
    std::vector&lt;double&gt; val;
    std::vector&lt;Node&gt; node;
};
static Tape T;

struct Var { int id; };

Var leaf(double x) {
    T.val.push_back(x);
    T.node.push_back({-1, -1, 0.0, 0.0});
    return {static_cast&lt;int&gt;(T.val.size()) - 1};
}

Var make(double v, int p1, double d1, int p2, double d2) {
    T.val.push_back(v);
    T.node.push_back({p1, p2, d1, d2});
    return {static_cast&lt;int&gt;(T.val.size()) - 1};
}

double value(Var a) { return T.val[a.id]; }

Var operator*(Var a, Var b) {
    return make(value(a) * value(b), a.id, value(b), b.id, value(a));
}
Var operator+(Var a, Var b) { return make(value(a) + value(b), a.id, 1.0, b.id, 1.0); }
Var vexp(Var a) {
    double e = std::exp(value(a));
    return make(e, a.id, e, -1, 0.0);
}

// Reverse sweep: nodes were appended in topological order, so walk backwards.
std::vector&lt;double&gt; reverse_sweep(Var out) {
    std::vector&lt;double&gt; adj(T.val.size(), 0.0);
    adj[out.id] = 1.0;
    for (int i = static_cast&lt;int&gt;(T.val.size()) - 1; i &gt;= 0; --i) {
        const Tape::Node&amp; n = T.node[i];
        if (n.p1 &gt;= 0) adj[n.p1] += adj[i] * n.d1;  // += accumulates shared inputs
        if (n.p2 &gt;= 0) adj[n.p2] += adj[i] * n.d2;
    }
    return adj;
}

int main() {
    Var x = leaf(2.0);
    Var y = leaf(3.0);
    Var f = x * y + vexp(x);  // f = x*y + exp(x), x used twice
    std::vector&lt;double&gt; adj = reverse_sweep(f);
    std::printf("f      = %.6f\n", value(f));
    std::printf("df/dx  = %.6f\n", adj[x.id]);
    std::printf("df/dy  = %.6f\n", adj[y.id]);
    std::printf("tape nodes = %zu\n", T.val.size());
    return 0;
}
</code></pre>
